{
  "implementation": "import math

def solve(case):
    # Validate required fields
    required = ["sentence_vectors", "query_vector", "context_weight"]
    for key in required:
        if key not in case:
            raise ValueError(f"Missing required field: {key}")

    sentence_vectors = case["sentence_vectors"]
    query_vector = case["query_vector"]
    context_weight = case["context_weight"]

    if not (isinstance(sentence_vectors, list) and len(sentence_vectors) > 0):
        raise ValueError("sentence_vectors must be a non-empty list")
    if not isinstance(query_vector, list) or len(query_vector) == 0:
        raise ValueError("query_vector must be a non-empty list")
    if not isinstance(context_weight, (int, float)):
        raise ValueError("context_weight must be a number")

    n = len(sentence_vectors)

    # Compute cosine similarities
    similarities = []
    for vec in sentence_vectors:
        dot = sum(a * b for a, b in zip(vec, query_vector))
        norm_vec = math.sqrt(sum(x*x for x in vec))
        norm_query = math.sqrt(sum(x*x for x in query_vector))
        if norm_vec == 0.0 or norm_query == 0.0:
            sim = 0.0
        else:
            sim = dot / (norm_vec * norm_query)
        similarities.append(sim)

    # Compute neighbor averages and blended scores
    scores = [0.0] * n
    for i in range(n):
        own = similarities[i]
        neighbor_sims = []
        if i > 0:
            neighbor_sims.append(similarities[i-1])
        if i < n - 1:
            neighbor_sims.append(similarities[i+1])
        if neighbor_sims:
            neighbor_avg = sum(neighbor_sims) / len(neighbor_sims)
        else:
            neighbor_avg = 0.0
        blended = (1.0 - context_weight) * own + context_weight * neighbor_avg
        scores[i] = round(blended, 6)

    # Rank by descending score then original index
    indexed = [(scores[i], i) for i in range(n)]
    indexed.sort(key=lambda x: (-x[0], x[1]))
    ranking = [0] * n
    for rank, (score, idx) in enumerate(indexed, start=1):
        ranking[idx] = rank

    return {"ranking": ranking, "scores": scores}
